from itertools import permutations
E=[('P','Q'),('R','Q'),('Q','S'),('Q','V'),('S','U'),('V','T')]
opts={'A':'PQRSTUV','B':'PRQVSUT','C':'PQRSVUT','D':'PRQSVTU'}
def bad(o):
    pos={v:i for i,v in enumerate(o)}
    return [f'{u}->{v}' for u,v in E if pos[u]>pos[v]]
for k,o in opts.items():
    assert sorted(o)==sorted('PQRSTUV')
    b=bad(o); print(k,' '.join(o),'VALID' if not b else 'INVALID, violated: '+', '.join(b))
allv=[p for p in permutations('PQRSTUV') if not bad(p)]
print('number of topological orders:',len(allv))  # 2 (P,R order) * C(4,2)=6 interleavings of S-U and V-T -> 12
